# coding:utf-8
from save import *
save({
'A0821-B0002':'第一次阿玛吉多顿战争是三场阿玛吉多顿战争中最鲜为人知的一场，交战双方为帝国与混沌。斯卡拉特拉克斯之战后，吞世者在背叛者卡恩的暴行中四分五裂；受恐虐宠爱的恶魔原体安格隆为重新集结军团准备多年，这次入侵正是其成果。',
'A0821-B0010':'结果：帝国惨胜',
'A0821-B0014':'指挥官：安格隆（遭放逐）、科索拉克斯、斯卡尔利克、汉斯·科伦、阿克尔·毁灭剥皮者／头狼洛根·格里姆纳尔、兄弟会连长塔雷玛·奥瑞利安（阵亡）、领主将军古斯塔夫·卡尔森二世',
'A0821-B0016':'损失：战败，安格隆被放逐回亚空间／数百万人',
'A0821-B0019':'战争发端于恐惧之眼。盘踞其中、效忠混沌的势力通常彼此厮杀，却偶尔会出于难以理解的缘由暂搁争端，共同进攻帝国。这一次，一艘名为群星吞噬者号的太空废船抵达某颗恶魔世界附近，促成了混沌势力集结。它体积庞大，足以载运一支巨军袭击帝国世界。444.M41，反复无常的亚空间潮流将这支入侵军带到了巢都世界阿玛吉多顿。',
'A0821-B0021':'与此同时，阿玛吉多顿接连发生怪事，最终有六座巢都爆发武装叛乱。该行星有三块主要陆地，大部分人口集中在主大陆。主大陆又分为阿玛吉多顿普赖姆地区与阿玛吉多顿塞孔杜斯地区，中间横亘着茂密的“赤道丛林”。塞孔杜斯的叛乱很快被平息，普赖姆的巢都分布更分散，叛乱则较难根除。行星防御部队看似足以应对，帝国便未派遣增援。阿玛吉多顿远离恐惧之眼，无人怀疑这场动乱背后藏着比普通内乱更险恶的阴谋。',
'A0821-B0023':'帝国部队正忙于平叛，群星吞噬者号突然抵达阿玛吉多顿星系，令他们措手不及。',
'A0821-B0024':'The Threat Realised 威胁显现',
'A0821-B0026':'群星吞噬者号载着恶魔原体安格隆统领的庞大混沌大军。吞世者军团的混沌星际战士、邪教徒、恶魔宿主、变种人、野兽人及成群恶魔涌出废船，降临阿玛吉多顿普赖姆地区。',
'A0821-B0028':'混沌的阴险影响很快显露：近半行星防御部队倒戈，加入入侵者。吞世者在嗜血欲驱使下扑向居民，仅最初几周便屠杀数百万人。仅存的忠诚守军迅速溃败，被逐出普赖姆。他们穿过南方丛林，与塞孔杜斯部队会合，准备沿斯提克斯河与卡戎河作最后的抵抗。',
'A0821-B0029':'Raising the Defenses 组织防御',
'A0821-B0031':'帝国的防御部署得井井有条。混沌大军并不知道，洛根·格里姆纳尔与他的太空野狼大连此时恰被派驻这一星区，迅速赶来援救。安格隆没有乘胜追击，反而用死者遗骸堆筑血腥纪念碑，使守军获得宝贵时间。此外，他的力量依赖附近的亚空间风暴；风暴稍歇，守军又有了组织反击的机会。等混沌大军穿过分隔普赖姆与塞孔杜斯的丛林时，太空野狼已加入防线，帝国严阵以待。格里姆纳尔的威仪与感召力让原本惊恐的守军重新振作。',
'A0821-B0033':'激战沿整条战线爆发。敌军数量虽达太空野狼的一千倍，格里姆纳尔仍率部冲锋。这位头狼统率装甲突击，径直渡过卡戎河，杀入吞世者阵中，重创叛军后撤退。暴怒的吞世者追着野狼机械化部队进入丛林，却落入太空野狼与钢铁军团沿河布设的联合伏击，遭到屠戮。野狼随后涉入河中，狂烈地迎击混沌大军，鏖战数小时，守住了防线。',
'A0821-B0035':'然而在西侧，沿斯提克斯河展开的攻势由安格隆及残酷者卫队亲自领衔。原体与麾下嗜血狂魔突破帝国防线，将大军引向炼狱巢都和赫尔斯利奇巢都。帝国卫队与太空野狼拼死阻击，终于争取到足够时间，让帝国得以投入灰骑士。',
'A0821-B0038':'帝国此时终于动用了秘密武器。格里姆纳尔认清敌人的本质后，便呼叫灰骑士支援：唯有审判庭恶魔猎手所属的这一武装战团，才有能力真正击败安格隆这般强大的恶魔。',
'A0821-B0040':'灰骑士派出一百零九名突击终结者，直接传送至恶魔大军中央，攻击安格隆及其十二名嗜血狂魔亲卫——残酷者卫队。与此同时，太空野狼率帝国军发起大规模反攻。起初，安格隆与亲卫重创灰骑士；原体挥动黑刃，一击便杀死五名终结者。然而，年轻新兵许珀里翁以强大灵能击碎黑刃，使灰骑士取得决定性的优势。随后，兄弟会连长塔雷玛·奥瑞利安亲自将安格隆放逐回亚空间，期限为一百年零一天，自己却也在此过程中战死。首领消失，加上帝国残军的突然反击，令混沌势力几乎全面溃败。失去安格隆后，其余恶魔也随之消散，邪教徒、变种人及叛军惊慌逃窜。星际战士与钢铁军团一路追入灰烬荒原，将其歼灭。帝国虽赢得大胜，灰骑士却仅有十三人生还。',
'A0821-B0043':'此后的岁月中，审判庭严密封锁第一次阿玛吉多顿战争的消息，以至于连当地居民也相信，这颗行星只经历过两场大战。',
'A0821-B0046':'虽然赢得战争，阿玛吉多顿的将士却难逃厄运。他们已知晓混沌存在，并接触其腐化。审判庭将除星际战士外、所有曾在行星上参战的人绝育，送入劳役营；随后从其他地区迁入对这场战争一无所知的人口，重新殖民阿玛吉多顿。审判庭与灰骑士继续清洗轨道上的帝国海军和机械修会舰船，灰骑士打击巡洋舰则摧毁正在离开的帝国卫队运兵船。附近三个世界的居民仅因听闻风暴兵在赫尔斯利奇之战中的功绩，也遭灭口。清洗共夺去数十亿生命。洛根·格里姆纳尔长期奋力阻止这一切，甚至派舰队护送幸存者逃离审判庭追捕；但恶魔审判庭与灰骑士发动攻击后，他未能阻止清洗。他始终无法原谅审判庭，认为这是对那些为家园、为帝国光荣作战者的背叛。凡接触过太空野狼所护送幸存者的世界，也遭到灭绝令打击：星语庭的拉斯·梅里迪安站、詹达拉五号、泰博尔德，以及机械修会的普里阿姆·诺维斯前哨，均因此毁灭。',
'A0821-B0047':'Order of battle 参战序列',
'A0821-B0058':'汉斯·科伦的夺颅者（一个连）',
'A0821-B0061':'Clysm 克利斯姆',
'A0821-B0063':'恐虐恶魔（“不计其数”）',
'A0821-B0087':'称义先民（一个大队）',
'A0821-B0114':'十三个阿玛吉多顿钢铁军团所属团',
'A0821-B0122':'Tempestus Scions 风暴忠嗣军',
'A0821-B0132':'Adeptus Mechanicus 机械修会',
'A0821-B0139':'与撕肉者战团长加百列·赛斯交谈时，审判官奈罗莎提出，地表下可能埋着一台叛徒泰坦军团的帝皇级泰坦，这或许正是欧克蛮人不断进攻阿玛吉多顿的原因。她认为，如此强大的战争机器遭恐虐腐化后，可能在潜意识层面一次次吸引绿皮前来。赛斯则指出，自阿玛吉多顿重新殖民以来，叛徒泰坦已数千年、乃至更久未曾踏上此地。也许审判官有意混淆第一次战争的历史，让人不知道它其实距今不远。然而，两人都清楚，当年不仅重新殖民，还曾对整颗行星的地貌进行彻底改造。奈罗莎认为，机械修会重塑地貌时遗漏了这项可怕威胁，只将其掩埋。相关叙述没有提到泰坦参与安格隆的军队；虽然这台帝皇级最终被认定属于歼灭者军团，赛斯与奈罗莎仍都确认，数千年前曾有叛徒泰坦在阿玛吉多顿作战。因此，所谓“第一次阿玛吉多顿战争”未必是混沌第一次入侵，也可能还有其他历史遭到审判庭掩盖。'
},[821],{
'A0821-B0021':'Prime与Secundus均为同一主大陆上的地区，不是阿玛吉多顿一号、二号行星。Prime沿核心普赖姆地区；Secundus暂作塞孔杜斯地区。',
'A0821-B0028':'went over to 指倒戈投敌，非仅投降。',
'A0821-B0033':'outnumbered one thousand to one 表示敌众我寡，明确敌军约为野狼一千倍，避免原译比例倒置。',
'A0821-B0040':'a dozen 为十二，非十几；decimated指重创，不是全部摧毁。Hyperion沿已校464许珀里翁；Brother-Captain按已核官方兄弟会连长。',
'A0821-B0061':'Clysm为战帮专名，原“冲洗者”疑按词源机械意译且无语境依据；暂音译克利斯姆，待核。',
'A0821-B0087':'Ancients 在此邪教名称中为先民／古老者，并非星际战士Ancient旗手职务；暂译称义先民。',
'A0821-B0139':'原文同时称没有提到安格隆部队有泰坦，而本篇参战序列又明确列出叛徒泰坦军团，存在资料间矛盾；保留并提示，不删除一方。末段各项均为人物推测或本文推论，未改成定论。'
})
with (P/'terms.tsv').open('a') as f:
 for en,zh,note in [('Armageddon Secundus','阿玛吉多顿塞孔杜斯地区','主大陆地区，非第二颗行星；与核心Prime普赖姆地区并列。'),('Equatorial Jungle','赤道丛林','大陆分界。'),('Styx','斯提克斯河','沿原稿河名。'),('Chaeron','卡戎河','沿原稿河名，英文非Charon亦不改英文。'),('Skchalick','斯卡尔利克','混沌领主。'),("Hans Kho’ren",'汉斯·科伦','沿原稿人物，撇号保留在英文。'),('Akor Doomflayer','阿克尔·毁灭剥皮者','沿原稿。'),('Gustav Karlson II','古斯塔夫·卡尔森二世','卫队领主将军。'),('Hive Infernus','炼狱巢都','与同名车辆/舰级分开。'),('Hive Helsreach','赫尔斯利奇巢都','沿原稿。'),('Ralas Meridian','拉斯·梅里迪安站','星语庭设施。'),('Jendara Quintus','詹达拉五号','沿原稿。'),('Tybuilt','泰博尔德','沿原稿。'),('Priam Novus','普里阿姆·诺维斯','机械修会前哨。'),('Clysm','克利斯姆','战帮名原冲洗者缺乏语境依据，暂音译。'),('The Justified Ancients','称义先民','邪教专名，Ancients非旗手。'),('Legio Vulcanum II','火神二号军团','沿原稿泰坦军团。'),('Legio Annihilator','歼灭者军团','沿原稿泰坦军团。'),('Metalica Battle Congregations','梅塔利卡战斗修会','沿原稿机械修会作战编制，非宗教教会。'),('Nerosa','奈罗莎','审判官。')]:f.write('\t'.join([en,zh,'暂定·官方待核','所给英文底稿','篇0821',note])+'\n')
